def build():
    for i, lg in enumerate(LANGS, 1):
        os.makedirs(os.path.join(HERE, lg), exist_ok=True)
        for name in ("about", "methodology", "privacy", "contact"):
            s = open(os.path.join(HERE, name + ".html"), encoding="utf-8").read()
            for row in sorted(T, key=lambda r: -len(r[0])):
                s = s.replace(row[0], row[i])
            s = s.replace('<html lang="en">', '<html lang="%s"%s>' % (lg, ' dir="rtl"' if lg == "ar" else ""), 1)
            # links stay in the language: /about -> /fr/about, / -> /fr/films
            s = re.sub(r'href="/(about|methodology|privacy|contact|news)"', lambda m: 'href="/%s/%s"' % (lg, m.group(1)) if m.group(1) != "news" else 'href="/news"', s)
            s = s.replace('href="/"', 'href="/%s/%s"' % (lg, SEC[lg]))
            s = s.replace('"item":"/"', '"item":"/%s/"' % lg).replace('"item":"/methodology"', '"item":"/%s/methodology"' % lg)
            if lg == "ar": s = s.replace("</style>", "ul{padding-left:0;padding-right:20px}</style>", 1)
            open(os.path.join(HERE, lg, name + ".html"), "w", encoding="utf-8", newline="\n").write(s)
    print("built", len(LANGS) * 4, "pages")

if __name__ == "__main__":
    build()
